package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.Zero
var WsNet decimal.Decimal = decimal.Zero
var WsTotalNet decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var DiscRecData DiscRec
var inputLines []string
var inputIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parsePrice(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	// keep only digits (and possible sign? assume digits)
	t = strings.TrimSpace(t)
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// fallback: strip non-digits
		digits := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			return decimal.Zero
		}
		n, _ = strconv.ParseInt(digits, 10, 64)
	}
	return decimal.New(n, -2)
}

func parsePct(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		digits := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			return 0
		}
		n, _ = strconv.ParseInt(digits, 10, 64)
	}
	return n
}

func store95v99(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	mod := decimal.New(1, 5)
	if d.IsNegative() {
		neg := d.Neg().Mod(mod)
		d = neg.Neg()
		if d.IsZero() {
			return decimal.Zero
		}
		return d
	}
	return d.Mod(mod)
}

func store98v99(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	mod := decimal.New(1, 8)
	if d.IsNegative() {
		neg := d.Neg().Mod(mod)
		d = neg.Neg()
		if d.IsZero() {
			return decimal.Zero
		}
		return d
	}
	return d.Mod(mod)
}

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatNumericEdited(v decimal.Decimal, pic string) string {
	var left, right string
	if idx := strings.Index(pic, "."); idx >= 0 {
		left = pic[:idx]
		right = pic[idx+1:]
	} else {
		left = pic
		right = ""
	}
	intDigits := 0
	for _, c := range left {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, c := range right {
		if c == 'Z' || c == '9' {
			decDigits++
		}
	}
	av := v.Abs().Truncate(int32(decDigits))
	scaled := av.Shift(int32(decDigits)).Truncate(0).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	divDec := pow10(decDigits)
	var frac int64
	var intPart int64
	if decDigits > 0 {
		frac = scaled % divDec
		intPart = scaled / divDec
	} else {
		frac = 0
		intPart = scaled
	}
	modInt := pow10(intDigits)
	if modInt != 0 {
		intPart = intPart % modInt
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	var fracStr string
	if decDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", decDigits, frac)
	}
	var b strings.Builder
	suppressed := true
	p := 0
	for _, c := range left {
		switch c {
		case 'Z':
			dch := intStr[p]
			p++
			if suppressed && dch == '0' {
				b.WriteByte(' ')
			} else {
				b.WriteByte(dch)
				suppressed = false
			}
		case '9':
			dch := intStr[p]
			p++
			b.WriteByte(dch)
			suppressed = false
		case ',':
			if suppressed {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		default:
			b.WriteByte(byte(c))
		}
	}
	if strings.Contains(pic, ".") {
		b.WriteByte('.')
		q := 0
		for _, c := range right {
			if c == '9' || c == 'Z' {
				if q < len(fracStr) {
					b.WriteByte(fracStr[q])
					q++
				} else {
					b.WriteByte('0')
				}
			} else {
				b.WriteByte(byte(c))
			}
		}
	}
	return b.String()
}

func formatCount(c int64) string {
	v := c % 1000
	if v < 0 {
		v += 1000
	}
	return fmt.Sprintf("%03d", v)
}

func formatPct(p int64) string {
	v := p % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line += strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	DiscRecData.DrItem = line[0:6]
	DiscRecData.DrPrice = parsePrice(line[6:13])
	DiscRecData.DrPct = parsePct(line[13:15])
}

func ProcessPara() {
	tmp := DiscRecData.DrPrice.Mul(decimal.NewFromInt(DiscRecData.DrPct)).Shift(-2)
	tmp = tmp.Round(2)
	WsDiscount = store95v99(tmp)
	diff := DiscRecData.DrPrice.Sub(WsDiscount)
	diff = diff.Truncate(2)
	WsNet = store95v99(diff)
	tot := WsTotalNet.Add(WsNet)
	tot = tot.Truncate(2)
	WsTotalNet = store98v99(tot)
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatNumericEdited(DiscRecData.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatNumericEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatNumericEdited(WsNet, "ZZ,ZZ9.99")
	fmt.Println(DiscRecData.DrItem+" "+WsPriceEd+" "+formatPct(DiscRecData.DrPct)+"% "+WsDiscEd+" "+WsNetEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatNumericEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	fmt.Println("ITEMS: "+formatCount(WsCount)+" NET TOTAL: "+WsTotalEd)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		const maxCap = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, maxCap)
		inputLines = nil
		for sc.Scan() {
			line := sc.Text()
			// Scanner with ScanLines already strips trailing \r
			inputLines = append(inputLines, line)
		}
		if err := sc.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			f.Close()
			os.Exit(1)
		}
		f.Close()
	}
	inputIdx = 0
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
